export const BUY_FORM = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>WISEN, pricing</title>\n<meta name=\"description\" content=\"A complete school ERP for Indian K-12 schools: admissions, attendance, fees, examinations, payroll and the UDISE+ return. Monthly or yearly, unlimited users.\">\n<link rel=\"stylesheet\" href=\"/static/app.css?v=@@V@@\">\n<script>\n  try {\n    var t = localStorage.getItem('theme');\n    if (t === 'dark' || t === 'light') document.documentElement.setAttribute('data-theme', t);\n  } catch (e) {}\n</script>\n<script>\n  \n\n  try {\n    var t = localStorage.getItem('theme');\n    if (t === 'dark' || t === 'light') document.documentElement.setAttribute('data-theme', t);\n  } catch (e) {}\n</script>\n</head>\n<body class=\"marketing pricing\">\n\n<header class=\"topbar\">\n  <span class=\"wordmark\">WISEN</span>\n  <span class=\"spacer\"></span>\n  <button type=\"button\" id=\"theme-toggle\" class=\"theme-toggle\"\n        aria-label=\"Switch between light and dark\" title=\"Switch appearance\">\n  <svg class=\"icon-moon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\"\n       stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n    <path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/>\n  </svg>\n  <svg class=\"icon-sun\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\"\n       stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n    <circle cx=\"12\" cy=\"12\" r=\"4\"/>\n    <path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41\"/>\n  </svg>\n</button>\n  <a class=\"quiet\" href=\"/login\">Sign in</a>\n</header>\n\n<main>\n  <section class=\"price-hero\">\n    <h1>Select your WISEN plan</h1>\n    <p class=\"lede\">Start today. Your school is set up the moment the payment clears.</p>\n\n    \n    <div class=\"billing\" id=\"billing\">\n      <span class=\"bill-label\" data-for=\"monthly\">Monthly</span>\n      <button type=\"button\" id=\"billing-toggle\" class=\"switch\" role=\"switch\"\n              aria-checked=\"true\" aria-label=\"Show monthly prices\">\n        <span class=\"knob\"></span>\n      </button>\n      <span class=\"bill-label on\" data-for=\"yearly\">\n        Yearly\n        <span class=\"save-tag\" id=\"save-tag\">save up to 33%</span>\n      </span>\n    </div>\n  </section>\n\n  <section class=\"tiers\" aria-label=\"Plans\">\n    \n  </section>\n\n  <section class=\"included\">\n    <h2>In every plan</h2>\n    <ul>\n      <li>Unlimited staff, student and parent accounts</li>\n      <li>Role-based access, so a teacher sees their classes and nobody else's</li>\n      <li>Daily backups, and your data stays in India</li>\n      <li>UDISE+ and APAAR fields on every student record</li>\n      <li>An audit trail of every change, which is what an inspection asks for</li>\n      <li>Setup and staff training included in the first year</li>\n    </ul>\n  </section>\n\n  <section class=\"enquire\" id=\"enquire\">\n    <h2>Would rather talk to somebody first?</h2>\n    <p class=\"lede\">\n      Leave your details and we will telephone you. No account is created and\n      nothing is charged.\n    </p>\n\n    \n      <p class=\"error\" role=\"alert\">@@ERROR@@</p>\n      <form method=\"post\" action=\"/buy\">\n        <div class=\"grid\">\n          <div class=\"row\">\n            <label for=\"school_name\">School name<span aria-hidden=\"true\">*</span></label>\n            <input id=\"school_name\" name=\"school_name\" value=\"@@SCHOOL@@\" required>\n          </div>\n          <div class=\"row\">\n            <label for=\"contact_name\">Your name<span aria-hidden=\"true\">*</span></label>\n            <input id=\"contact_name\" name=\"contact_name\" value=\"@@CONTACT@@\" required>\n          </div>\n          <div class=\"row\">\n            <label for=\"email\">Email</label>\n            <input id=\"email\" name=\"email\" type=\"email\" value=\"@@EMAIL@@\">\n          </div>\n          <div class=\"row\">\n            <label for=\"phone\">Phone</label>\n            <input id=\"phone\" name=\"phone\" value=\"@@PHONE@@\">\n          </div>\n          <div class=\"row\">\n            <label for=\"district\">District</label>\n            <input id=\"district\" name=\"district\" value=\"@@DISTRICT@@\">\n          </div>\n          <div class=\"row\">\n            <label for=\"students\">How many students?</label>\n            <input id=\"students\" name=\"students\" inputmode=\"numeric\" value=\"@@STUDENTS@@\">\n          </div>\n        </div>\n        <div class=\"row\">\n          <label for=\"plan_code\">Plan you are considering</label>\n          <select id=\"plan_code\" name=\"plan_code\">\n            <option value=\"\">Not sure yet</option>\n            \n          </select>\n        </div>\n        <div class=\"row\">\n          <label for=\"message\">Anything you want us to know</label>\n          <textarea id=\"message\" name=\"message\" rows=\"3\">@@MESSAGE@@</textarea>\n        </div>\n        <button type=\"submit\">Ask us to call</button>\n      </form>\n    \n  </section>\n</main>\n\n<footer class=\"foot\">\n  <a href=\"/login\">Sign in</a> · <a href=\"#enquire\">Talk to us</a>\n</footer>\n\n<script>\n\n\n(function () {\n  var toggle = document.getElementById('billing-toggle');\n  if (!toggle) return;\n  var wrap = document.getElementById('billing');\n  var tag = document.getElementById('save-tag');\n  var yearly = true;\n\n  function apply() {\n    document.querySelectorAll('.figure, .per').forEach(function (el) {\n      var v = el.getAttribute(yearly ? 'data-yearly' : 'data-monthly');\n      if (v) el.textContent = v;\n    });\n    document.querySelectorAll('.tier-save[data-saving]').forEach(function (el) {\n      el.textContent = yearly\n        ? 'Paying yearly saves ' + el.getAttribute('data-saving') + '%'\n        : 'Save ' + el.getAttribute('data-saving') + '% by paying yearly';\n    });\n    \n    \n    document.querySelectorAll('.tier-cta').forEach(function (a) {\n      a.setAttribute('href', '/signup?plan=' + a.getAttribute('data-plan') +\n        '&billing=' + (yearly ? 'yearly' : 'monthly'));\n    });\n    wrap.querySelectorAll('.bill-label').forEach(function (l) {\n      l.classList.toggle('on', l.getAttribute('data-for') === (yearly ? 'yearly' : 'monthly'));\n    });\n    toggle.setAttribute('aria-checked', String(yearly));\n    toggle.classList.toggle('off', !yearly);\n    if (tag) tag.hidden = !yearly;\n  }\n\n  toggle.addEventListener('click', function () { yearly = !yearly; apply(); });\n  apply();\n})();\n\n\n\n\n(function () {\n  var fine = true, ok = true;\n  try {\n    fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;\n    ok = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  } catch (e) {}\n  if (!fine || !ok) return;\n\n  document.querySelectorAll('.tier').forEach(function (card) {\n    card.addEventListener('pointermove', function (e) {\n      var b = card.getBoundingClientRect();\n      card.style.setProperty('--mx', (e.clientX - b.left) + 'px');\n      card.style.setProperty('--my', (e.clientY - b.top) + 'px');\n    });\n    card.addEventListener('pointerleave', function () {\n      card.style.removeProperty('--mx');\n      card.style.removeProperty('--my');\n    });\n  });\n})();\n</script>\n\n<script>\n(function () {\n  var btn = document.getElementById('theme-toggle');\n  if (!btn) return;\n  var root = document.documentElement;\n  btn.addEventListener('click', function () {\n    var now = root.getAttribute('data-theme') ||\n      (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');\n    var next = now === 'dark' ? 'light' : 'dark';\n    root.setAttribute('data-theme', next);\n    try { localStorage.setItem('theme', next); } catch (e) {}\n  });\n})();\n</script>\n</body>\n</html>"
